def write_reports():
    inv=json.loads((OUT/'python_copy_inventory.json').read_text(encoding='utf-8'))
    parts=['# Saffron Chinese audit — engine-owned copy\n\n2026-09-10. Exact source wording is preserved below. Line numbers refer to this review snapshot. This is an editorial proposal, not a production patch.\n\nEvery `_t(en, zh)` unit in the three active content engines was read. Neutral names, quantities, currencies and already-clear labels are retained unless flagged. A retained numeric literal is **not** factual approval: numeric tables remain subject to the model/source blockers in the improvement brief. “Hold” entries provide safe draft wording but must not be shipped with the old model. English must be corrected alongside Chinese wherever the underlying claim changes.\n\nFor f-strings, `{...}` preserves the source expression; implementers must retain real interpolation rather than paste expressions into the UI.\n']
    stats={}
    for file in [F,B,R,O]:
        group=[r for r in inv if r['file']==file]
        parts.append('\n## '+file+'\n')
        for i,row in enumerate(group,1):
            exact=(file,row['line'],row['zh'])
            decision=EDITS.get(exact,EDITS.get((file,row['line'],None)))
            if file==O and row['line']!=75:
                decision=('', 'Not rendered by current Saffron. Do not spend the next release polishing unmounted etiquette copy.', 'Out of current UI')
            if decision:
                new,why,status=decision
            else:
                new=row['zh']; why='Clear label, proper name or numeric cell. Retain wording; verify factual/numeric fields under the cross-cutting checks.'; status='Retain wording'
            stats[status]=stats.get(status,0)+1
            ref=f"[{file}:{row['line']}](C:/ScottStuff/GalleryAgentAI/{file}:{row['line']})"
            parts += [f'\n### {file.split("/")[-1]} · {i:03d} · {status}\n\n{ref}\n\n**Current**\n\n'+ '\n'.join('> '+s for s in row['zh'].split('\n'))+'\n']
            if status not in ['Retain wording','Out of current UI']:
                parts.append('\n**Replace with**\n\n'+new+'\n')
            parts.append('\n**Reason:** '+why+'\n')
    (OUT/'02-Chinese-engine-copy.md').write_text('\n'.join(parts),encoding='utf-8')
    data=json.loads((OUT/'ladders_snapshot.json').read_text(encoding='utf-8'))
    rows=[]
    def walk(o,p=''):
        if isinstance(o,dict):
            if 'zh' in o and 'en' in o: rows.append((p,o['zh'])); return
            for k,v in o.items():walk(v,p+'.'+k if p else k)
        elif isinstance(o,list):
            for i,v in enumerate(o):walk(v,p+'.'+str(i))
    walk(data)
    parts=['# Saffron Chinese audit — all strategy ladder copy\n\nSource: [strategy_ladders.js](C:/ScottStuff/GalleryAgentAI/frontend/src/data/strategy_ladders.js). Exact object paths are stable locators. Every Chinese leaf was reviewed, including all expanded treatments. These prose proposals accompany a structural recommendation to replace scored ladders with evidence and optional sequences; changing labels alone does not correct the evidence rules.\n']
    for p,old in rows:
        dec=LADDER_EDITS.get(p)
        parts.append('\n## '+p+(' — Rewrite' if dec else ' — Retain')+'\n\n**Current:** '+old+'\n')
        if dec:parts.append('\n**Replace with:** '+dec[0]+'\n\n**Reason:** '+dec[1]+'\n')
    (OUT/'03-Chinese-strategy-ladders.md').write_text('\n'.join(parts),encoding='utf-8')
    (OUT/'copy_decision_summary.json').write_text(json.dumps({'engine_units':len(inv),'engine_decisions':stats,'ladder_units':len(rows),'ladder_rewrites':len(LADDER_EDITS)},indent=2),encoding='utf-8')
    print(json.dumps({'engine_units':len(inv),'engine_decisions':stats,'ladder_units':len(rows),'ladder_rewrites':len(LADDER_EDITS)}))

if __name__=='__main__':write_reports()
